import pandas as pd
import numpy as np
from pandas import testing as tm

# Test 1: td = pd.Timedelta(0, unit) with unit in ["s","ms","us","ns"]; factor in [np.inf, -np.inf, np.float32("inf")]; assert td * factor is pd.NaT
units = ["s", "ms", "us", "ns"]
factors = [np.inf, -np.inf, np.float32("inf")]
try:
    for unit in units:
        for factor in factors:
            td = pd.Timedelta(0, unit=unit)
            result = td * factor
            assert result is pd.NaT, f"td * factor with unit={unit}, factor={factor} returned {result}, expected pd.NaT"
    probe("td = pd.Timedelta(0, unit) with unit in [\"s\",\"ms\",\"us\",\"ns\"]; factor in [np.inf, -np.inf, np.float32(\"inf\")]; assert td * factor is pd.NaT", True)
except Exception as e:
    probe_exception("td = pd.Timedelta(0, unit) with unit in [\"s\",\"ms\",\"us\",\"ns\"]; factor in [np.inf, -np.inf, np.float32(\"inf\")]; assert td * factor is pd.NaT", e)

# Test 2: factor * td with td = pd.Timedelta(0, unit); assert factor * td is pd.NaT
try:
    for unit in units:
        for factor in factors:
            td = pd.Timedelta(0, unit=unit)
            result = factor * td
            assert result is pd.NaT, f"factor * td with unit={unit}, factor={factor} returned {result}, expected pd.NaT"
    probe("factor * td with td = pd.Timedelta(0, unit); assert factor * td is pd.NaT", True)
except Exception as e:
    probe_exception("factor * td with td = pd.Timedelta(0, unit); assert factor * td is pd.NaT", e)

# Test 3: td * np.array([factor]) compared with tm.assert_numpy_array_equal under np.errstate(invalid="ignore")
try:
    with np.errstate(invalid="ignore"):
        for unit in units:
            for factor in factors:
                td = pd.Timedelta(0, unit=unit)
                result = td * np.array([factor])
                expected = np.array([pd.NaT])
                tm.assert_numpy_array_equal(result, expected)
    probe("td * np.array([factor]) compared with tm.assert_numpy_array_equal under np.errstate(invalid=\"ignore\")", True)
except Exception as e:
    probe_exception("td * np.array([factor]) compared with tm.assert_numpy_array_equal under np.errstate(invalid=\"ignore\")", e)

# Test 4: Multiplying a zero Timedelta by inf (GH#68392) - whatsnew entry
try:
    td = pd.Timedelta(0, unit="ns")
    result = td * np.inf
    assert result is pd.NaT, f"Multiplying a zero Timedelta by inf returned {result}, expected pd.NaT"
    probe("Multiplying a zero Timedelta by inf (GH#68392) - whatsnew entry", True)
except Exception as e:
    probe_exception("Multiplying a zero Timedelta by inf (GH#68392) - whatsnew entry", e)

